import assert from'node:assert/strict';import fs from'node:fs';import path from'node:path';import http from'node:http';import https from'node:https';import net from'node:net';import{once}from'node:events';import{verifyProxyEgress}from'../../src/services/proxyEgressVerification.js';
const dir=process.argv[2],sockets=new Set();let status=200,body='{"ip":"203.0.113.9"}',drop=false;const origin=https.createServer({key:fs.readFileSync(path.join(dir,'key.pem')),cert:fs.readFileSync(path.join(dir,'cert.pem'))},(req,res)=>{assert.ok(['api.ipify.org','www.cloudflare.com'].includes(req.socket.servername));res.writeHead(status,{'content-type':'application/json'});res.end(body);}),proxy=http.createServer();proxy.on('connect',(req,client,head)=>{assert.ok(['api.ipify.org:443','www.cloudflare.com:443'].includes(req.url));sockets.add(client);client.on('close',()=>sockets.delete(client));if(drop)return;const target=net.connect(origin.address().port,'127.0.0.1',()=>{client.write('HTTP/1.1 200 Connection Established\r\n\r\n');if(head.length)target.write(head);target.pipe(client);client.pipe(target);});sockets.add(target);target.on('close',()=>sockets.delete(target));client.on('error',()=>target.destroy());target.on('error',()=>client.destroy());});for(const server of [origin,proxy]){server.listen(0,'127.0.0.1');await once(server,'listening');}
const value={host:'127.0.0.1',port:proxy.address().port};try{assert.equal(await verifyProxyEgress(value),'203.0.113.9');for(const [code,data]of [[302,'{"ip":"203.0.113.9"}'],[200,'{"ip":"fake"}'],[200,'bad json'],[200,'x'.repeat(2048)]]){status=code;body=data;await assert.rejects(verifyProxyEgress(value));}status=200;body='fl=echo\nip=203.0.113.10\ntls=TLSv1.3\n';assert.equal(await verifyProxyEgress(value,{service:'cloudflare'}),'203.0.113.10');status=429;await assert.rejects(verifyProxyEgress(value,{service:'cloudflare'}),e=>e.responseObserved===true);await assert.rejects(verifyProxyEgress(value,{service:'unknown'}),e=>e.code==='PROXY_EGRESS_CONFIG_INVALID');drop=true;await assert.rejects(verifyProxyEgress(value,{timeoutMs:50}),e=>e.responseObserved===false&&e.code==='ABORT_ERR');console.log('TLS_VERIFIED_EGRESS_AND_FAILURES_CHECKED');}finally{for(const s of sockets)s.destroy();for(const server of [origin,proxy]){server.closeAllConnections?.();await new Promise(resolve=>server.close(resolve));}}
